import re
data = open(GRAPH_TTL,'r',encoding='utf-8').read()
blocks = re.split(r'\n(?=bldg:)', data)
refs = {}
for b in blocks:
    m = re.match(r'(\S+)', b)
    name = m.group(1)
    if 'Zone_Air_Temperature_Sensor' in b or 'Electric_Power_Sensor' in b:
        refm = re.search(r'tsref:([0-9a-f-]+)', b)
        refs[name] = refm.group(1) if refm else None
for k,v in sorted(refs.items()):
    print(k, v)

import csv
# monthly averages for F3_Z01 and a peer zone
def load(ts):
    out={}
    with open(VALUES_CSV) as f:
        r=csv.DictReader(f)
        for row in r:
            if row['timeseries_id']==ts:
                out[row['timestamp']]=float(row['value'])
    return out
f3z1=load('e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8')
f2z5=load('108335ab-9ad0-5222-b9a5-88d998152c65')
def avg(d,ym):
    v=[x for t,x in d.items() if t.startswith(ym)]
    return sum(v)/len(v)
for m in ['2018-06','2018-07','2018-08','2018-09','2018-10']:
    a=avg(f3z1,m); b=avg(f2z5,m)
    print(m, f"F3Z01={a:.3f}  F2Z05={b:.3f}  diff={a-b:+.3f}")
